INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7737552, 1275600, 96751, '<td valign="top">Such beautiful light.</td>', 'Such beautiful light.', '2023-02-01 01:12:14.000000', NULL, 1),
(7737553, 1275698, 114285, '<td valign="top">Gorgeous photo. I love the editing.</td>', 'Gorgeous photo. I love the editing.', '2023-02-01 03:24:02.000000', NULL, 1),
(7737562, 1275742, 29535, '<td valign="top">I feel like extra effort has been made here to really capture a dynamic landscape photo. It''s a beautiful sky and I like the railroad tracks leading in. The horizon feels ever so slightly low on the right side. Do you live near this location? What a great place to have nearby for photos!</td>', 'I feel like extra effort has been made here to really capture a dynamic landscape photo. It''s a beautiful sky and I like the railroad tracks leading in. The horizon feels ever so slightly low on the right side. Do you live near this location? What a great place to have nearby for photos!', '2023-02-01 04:22:45.000000', NULL, 1),
(7737563, 1275785, 29535, '<td valign="top">He''s a funny-lookin'' fella! Great catch and the perfect example of when a typical bird photograph is elevated by being a surprising species. Even non-bird-lovers must appreciate this quirky guy.</td>', 'He''s a funny-lookin'' fella! Great catch and the perfect example of when a typical bird photograph is elevated by being a surprising species. Even non-bird-lovers must appreciate this quirky guy.', '2023-02-01 04:24:41.000000', NULL, 1),
(7737564, 1275813, 29535, '<td valign="top">Abstract... I''m not 100% sure what I''m looking at but there''s a certain order in the chaos that is really beautiful. Great choice for a free study, that''s what they''re about right?</td>', 'Abstract... I''m not 100% sure what I''m looking at but there''s a certain order in the chaos that is really beautiful. Great choice for a free study, that''s what they''re about right?', '2023-02-01 04:26:33.000000', NULL, 1),
(7737565, 1275764, 29535, '<td valign="top">King o''the world! Love this.</td>', 'King o''the world! Love this.', '2023-02-01 04:28:36.000000', NULL, 1),
(7737566, 1275783, 29535, '<td valign="top">I bet you''re kicking yourself at the new ''Adrift'' challenge popping up today! Really nice reflections here. I suspect we''ll be seeing a few nice shots from this day out with conditions like that :)</td>', 'I bet you''re kicking yourself at the new ''Adrift'' challenge popping up today! Really nice reflections here. I suspect we''ll be seeing a few nice shots from this day out with conditions like that :)', '2023-02-01 04:30:02.000000', NULL, 1),
(7737567, 1275698, 29535, '<td valign="top">As someone who really wants to produce nice woodland photography, I appreciate this photo is a lot more difficult than it looks and you''ve done a great job finding a composition which frames the trees beautifully and has a sky which compliments everything. Well done!</td>', 'As someone who really wants to produce nice woodland photography, I appreciate this photo is a lot more difficult than it looks and you''ve done a great job finding a composition which frames the trees beautifully and has a sky which compliments everything. Well done!', '2023-02-01 04:31:20.000000', NULL, 1),
(7737568, 1275796, 29535, '<td valign="top">A masterclass in landscape composition, focus and depth of field. That''s a difficult exposure to pull off as well. Add in the unpredictable nature of dogs and this seems like a very challenging and fortunate shot. Very nice!</td>', 'A masterclass in landscape composition, focus and depth of field. That''s a difficult exposure to pull off as well. Add in the unpredictable nature of dogs and this seems like a very challenging and fortunate shot. Very nice!', '2023-02-01 04:32:56.000000', NULL, 1),
(7737569, 1275812, 29535, '<td valign="top">Controversial! Vote as if the image was meant to be landscape and it''s an innocent mistake or vote like it was intentional and an artistic choice? And does it matter? Landscape I like the reflections of the boulder and the branch. Portrait it feels like a tree with a great grey moon above in the sky.<br/> <br/>I like both, nice job!</td>', 'Controversial! Vote as if the image was meant to be landscape and it''s an innocent mistake or vote like it was intentional and an artistic choice? And does it matter? Landscape I like the reflections of the boulder and the branch. Portrait it feels like a tree with a great grey moon above in the sky. I like both, nice job!', '2023-02-01 04:37:39.000000', NULL, 1),
(7737583, 1275736, 91360, '<td valign="top">I think this guy is Australian. I think I saw once his brother. They are very pretty with the green background:)</td>', 'I think this guy is Australian. I think I saw once his brother. They are very pretty with the green background:)', '2023-02-01 10:53:09.000000', NULL, 1),
(7737584, 1275766, 96751, '<td valign="top">Based purely on content, I''m guessing this is Bear...<br/> <br/>I just love your spirit.</td>', 'Based purely on content, I''m guessing this is Bear... I just love your spirit.', '2023-02-01 11:32:54.000000', NULL, 1),
(7737585, 1275812, 96751, '<td valign="top">Amazing what a simple rotation can do to an image. Love the trio of elements, which seem balanced in a precarious dance between life and mystery. Wish it were a tad brighter.</td>', 'Amazing what a simple rotation can do to an image. Love the trio of elements, which seem balanced in a precarious dance between life and mystery. Wish it were a tad brighter.', '2023-02-01 11:35:53.000000', NULL, 1),
