(7737762, 1275708, 97225, '<td valign="top">Gorgeous colours and patterns. My top pick. 10</td>', 'Gorgeous colours and patterns. My top pick. 10', '2023-02-04 20:53:31.000000', NULL, 1),
(7737778, 1275770, 273752, '<td valign="top">So much to like about this.  How the snow pops off his fur and the disc, the texture of the snow popping off the image, the contrast of the black and white, the movement the image conveys...really good image.</td>', 'So much to like about this.  How the snow pops off his fur and the disc, the texture of the snow popping off the image, the contrast of the black and white, the movement the image conveys...really good image.', '2023-02-04 21:54:33.000000', NULL, 1),
(7737779, 1275785, 273752, '<td valign="top">Great DOF, great colors, love the texture the bird''s feathers show in this image.</td>', 'Great DOF, great colors, love the texture the bird''s feathers show in this image.', '2023-02-04 21:55:37.000000', NULL, 1),
(7737780, 1275773, 273752, '<td valign="top">A lot to like here.  The key contrast is excellent.  The colors are spot on.  I see strong shapes connecting the glassware, which I like very much.  Well done.</td>', 'A lot to like here.  The key contrast is excellent.  The colors are spot on.  I see strong shapes connecting the glassware, which I like very much.  Well done.', '2023-02-04 21:57:27.000000', NULL, 1),
